                        q = r + dr, c + dc
                        if q in cells:
                            cells.remove(q)
                            todo.append(q)
            rs = [r for r, c in comp]
            cs = [c for r, c in comp]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            a = [[grid[r][c] for c in range(c0, c1 + 1)]
                 for r in range(r0, r1 + 1)]
            if not any(x == fill for row in a for x in row):
                continue
            ans.append({'a': a, 'r': (r0+r1)/2, 'c': (c0+c1)/2,
                        'r0': r0, 'r1': r1, 'c0': c0, 'c1': c1})
        return ans

    def solid(row):
        return all(x == frame for x in row)

    def sides(a):
        return (solid(a[0]), solid(a[-1]),
                all(row[0] == frame for row in a),
                all(row[-1] == frame for row in a))

    def orient(a, top, left):
        a = [row[:] for row in a]
        t, b, l, r = sides(a)
        if t != top and b == top:
            a.reverse()
        t, b, l, r = sides(a)
        if l != left and r == left:
            a = [row[::-1] for row in a]
        return a

    # Split components at a complete horizontal frame. Each rectangle is an
    # independent quadrant of the reconstructed picture.
    all_rects = []
    for f in fills:
        for o in components(f):
